pub fn all_characters_same(s: &[u8]) -> bool {
    // Arrays of length 0 or 1 trivially have all identical characters.
    if s.len() <= 1 {
        return true;
    }

    // Grab the first byte and verify every other byte matches it.
    let first = s[0];
    s.iter().all(|&b| b == first)
}

